INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-TS006', 'HDSAT-RW-M34-TS006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'Open-source software (OSS) is computer software released under a license allowing users to use, study, modify, and distribute it to anyone for any purpose – in contrast to proprietary (closed-source) software. These abilities are typically granted through open licenses or, more rarely, by dedication to the public domain. The development of open-source software can be based on open collaboration, a decentralized model of production. Open-source software is commonly defined according to The Open Source Definition of the Open Source Initiative, but the precise meaning of "open source" remains contentious. Open-source software offers a range of benefits, but also presents specific risks and challenges. It can provide improved accessibility through lower and shared costs, greater adaptability through customization, transparency with auditable code, better interoperability via open standards, and independence from vendor lock-in, among others. The ubiquity of open-source software raises cybersecurity concerns and maintenance challenges. Open-source software has become the backbone of the global digital infrastructure, powering domains such as web servers, cloud computing, supercomputers, mobile devices, artificial intelligence, and Internet of Things. A 2022 estimate suggests that between 80 and 96 percent of the code making up software on the market today, including proprietary software, is of open-source origin.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It explains how to write an open-source license."}, {"id": "B", "text": "It argues that all software should be proprietary."}, {"id": "C", "text": "It compares two specific software projects."}, {"id": "D", "text": "It defines open-source software, describes its collaboration model and tradeoffs, and notes its role in infrastructure."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Open-source software", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Open-source_software', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-TS006', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition to benefits and risks, then prevalence.', '{"A": "No license drafting guidance is given.", "C": "No specific projects are compared.", "B": "The text describes open-source benefits without arguing for universal adoption."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-CE006', 'HDSAT-RW-M34-CE006', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'Open-source software (OSS) is computer software released under a license allowing users to use, study, modify, and distribute it to anyone for any purpose – in contrast to proprietary (closed-source) software. These abilities are typically granted through open licenses or, more rarely, by dedication to the public domain. The development of open-source software can be based on open collaboration, a decentralized model of production. Open-source software is commonly defined according to The Open Source Definition of the Open Source Initiative, but the precise meaning of "open source" remains contentious. Open-source software offers a range of benefits, but also presents specific risks and challenges. It can provide improved accessibility through lower and shared costs, greater adaptability through customization, transparency with auditable code, better interoperability via open standards, and independence from vendor lock-in, among others. The ubiquity of open-source software raises cybersecurity concerns and maintenance challenges. Open-source software has become the backbone of the global digital infrastructure, powering domains such as web servers, cloud computing, supercomputers, mobile devices, artificial intelligence, and Internet of Things. A 2022 estimate suggests that between 80 and 96 percent of the code making up software on the market today, including proprietary software, is of open-source origin.', 'Which quotation from the text most directly supports the claim that open-source licenses permit modification and redistribution?', '[{"id": "A", "text": "A 2022 estimate suggests that between 80 and 96 percent of the code making up software on the market today is of open-source origin."}, {"id": "B", "text": "Open-source software offers a range of benefits, but also presents specific risks and challenges."}, {"id": "C", "text": "The development of open-source software can be based on open collaboration, a decentralized model of production."}, {"id": "D", "text": "Open-source software (OSS) is computer software released under a license allowing users to use, study, modify, and distribute it to anyone for any purpose – in contrast to proprietary (closed-source) software."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Open-source software", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Open-source_software', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-CE006', 'D', ARRAY['D']::TEXT[], 'The correct quotation lists use, study, modification, and distribution rights.', '{"C": "This sentence describes the collaboration model.", "B": "This sentence describes benefits and risks.", "A": "This sentence gives a prevalence estimate."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-CI007', 'HDSAT-RW-M34-CI007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'In computer science, computer engineering, and telecommunications, a network is a group of communicating computers and peripherals called hosts, which communicate data to other hosts via communication protocols, as facilitated by networking hardware. Within a computer network, hosts are identified by network addresses, which allow networking hardware to locate and identify hosts. Hosts may also have hostnames, memorable labels for the host nodes, which can be mapped to a network address using a hosts file or a name server such as Domain Name Service. The physical medium that supports information exchange includes wired media like copper cables, optical fibers, and wireless radio-frequency media. The arrangement of hosts and hardware within a network architecture is called the network topology. The first computer network was created in 1940 when George Stibitz connected a terminal at Dartmouth to his Complex Number Calculator at Bell Labs in New York. Today, almost all computers are connected to a computer network, such as the global Internet or embedded networks such as those found in many modern electronic devices. Many applications have only limited functionality unless they are connected to a network. Networks support applications and services, such as access to the World Wide Web, digital video and audio, application and storage servers, printers, and email and instant messaging applications.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "A computer network is a group of hosts that communicate through protocols and hardware, identified by addresses and arranged in topologies."}, {"id": "B", "text": "The first computer network was created in 2020."}, {"id": "C", "text": "A computer network consists of a single host."}, {"id": "D", "text": "Networks do not use addresses or protocols."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Computer network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Computer_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-CI007', 'A', ARRAY['A']::TEXT[], 'The passage defines networks, describes addressing and hardware, and traces their history and uses.', '{"C": "The text defines a network as a group of communicating computers and peripherals.", "D": "The text says hosts communicate via protocols and are identified by network addresses.", "B": "The text says the first computer network was created in 1940."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-INF007', 'HDSAT-RW-M34-INF007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In computer science, computer engineering, and telecommunications, a network is a group of communicating computers and peripherals called hosts, which communicate data to other hosts via communication protocols, as facilitated by networking hardware. Within a computer network, hosts are identified by network addresses, which allow networking hardware to locate and identify hosts. Hosts may also have hostnames, memorable labels for the host nodes, which can be mapped to a network address using a hosts file or a name server such as Domain Name Service. The physical medium that supports information exchange includes wired media like copper cables, optical fibers, and wireless radio-frequency media. The arrangement of hosts and hardware within a network architecture is called the network topology. The first computer network was created in 1940 when George Stibitz connected a terminal at Dartmouth to his Complex Number Calculator at Bell Labs in New York. Today, almost all computers are connected to a computer network, such as the global Internet or embedded networks such as those found in many modern electronic devices. Many applications have only limited functionality unless they are connected to a network. Networks support applications and services, such as access to the World Wide Web, digital video and audio, application and storage servers, printers, and email and instant messaging applications.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-INF007', 'A', ARRAY['A']::TEXT[], 'Addresses exist so hardware can find and identify hosts on the network.', '{"D": "The text says addresses allow networking hardware to locate and identify hosts.", "C": "That contradicts the stated function.", "B": "Hostnames can map to addresses, but hardware uses addresses."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-TS007', 'HDSAT-RW-M34-TS007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Craft and Structure', 'Text Structure and Purpose', 'Medium', 'multiple_choice', 'In computer science, computer engineering, and telecommunications, a network is a group of communicating computers and peripherals called hosts, which communicate data to other hosts via communication protocols, as facilitated by networking hardware. Within a computer network, hosts are identified by network addresses, which allow networking hardware to locate and identify hosts. Hosts may also have hostnames, memorable labels for the host nodes, which can be mapped to a network address using a hosts file or a name server such as Domain Name Service. The physical medium that supports information exchange includes wired media like copper cables, optical fibers, and wireless radio-frequency media. The arrangement of hosts and hardware within a network architecture is called the network topology. The first computer network was created in 1940 when George Stibitz connected a terminal at Dartmouth to his Complex Number Calculator at Bell Labs in New York. Today, almost all computers are connected to a computer network, such as the global Internet or embedded networks such as those found in many modern electronic devices. Many applications have only limited functionality unless they are connected to a network. Networks support applications and services, such as access to the World Wide Web, digital video and audio, application and storage servers, printers, and email and instant messaging applications.', 'Which choice best describes the overall structure of the text?', '[{"id": "A", "text": "It compares wired and wireless speeds in a table."}, {"id": "B", "text": "It argues that networks are unnecessary."}, {"id": "C", "text": "It explains how to configure a home router."}, {"id": "D", "text": "It defines computer networks, describes their components and addressing, and notes their history and applications."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Computer network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Computer_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-TS007', 'D', ARRAY['D']::TEXT[], 'The passage moves from definition to architecture and then to history and uses.', '{"C": "No configuration steps are given.", "A": "No speed table appears.", "B": "The text says many applications have limited functionality without networks."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-CE007', 'HDSAT-RW-M34-CE007', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Command of Evidence (Textual)', 'Medium', 'multiple_choice', 'In computer science, computer engineering, and telecommunications, a network is a group of communicating computers and peripherals called hosts, which communicate data to other hosts via communication protocols, as facilitated by networking hardware. Within a computer network, hosts are identified by network addresses, which allow networking hardware to locate and identify hosts. Hosts may also have hostnames, memorable labels for the host nodes, which can be mapped to a network address using a hosts file or a name server such as Domain Name Service. The physical medium that supports information exchange includes wired media like copper cables, optical fibers, and wireless radio-frequency media. The arrangement of hosts and hardware within a network architecture is called the network topology. The first computer network was created in 1940 when George Stibitz connected a terminal at Dartmouth to his Complex Number Calculator at Bell Labs in New York. Today, almost all computers are connected to a computer network, such as the global Internet or embedded networks such as those found in many modern electronic devices. Many applications have only limited functionality unless they are connected to a network. Networks support applications and services, such as access to the World Wide Web, digital video and audio, application and storage servers, printers, and email and instant messaging applications.', 'Which quotation from the text most directly supports the claim that hosts are identified by network addresses?', '[{"id": "A", "text": "A network is a group of communicating computers and peripherals called hosts."}, {"id": "B", "text": "The physical medium that supports information exchange includes wired media like copper cables, optical fibers, and wireless radio-frequency media."}, {"id": "C", "text": "Within a computer network, hosts are identified by network addresses, which allow networking hardware to locate and identify hosts."}, {"id": "D", "text": "The first computer network was created in 1940 when George Stibitz connected a terminal at Dartmouth to his Complex Number Calculator."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Computer network", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Computer_network', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-CE007', 'C', ARRAY['C']::TEXT[], 'The correct quotation states that network addresses identify hosts.', '{"A": "This sentence defines a network.", "B": "This sentence describes physical media.", "D": "This sentence describes the first network."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-CI008', 'HDSAT-RW-M34-CI008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'In mathematics and computer science, an algorithm ( ) is a finite sequence of mathematically rigorous instructions, typically used to solve a class of specific problems or to perform a computation. Algorithms are used as specifications for performing calculations and data processing. More advanced algorithms can use conditionals to divert the code execution through various routes (referred to as automated decision-making) and deduce valid inferences (referred to as automated reasoning), achieving automation eventually. Using human characteristics as descriptors of machines in metaphorical ways was already practiced by Alan Turing with terms such as "memory", "search" and "stimulus". In contrast, a heuristic is an approach to problem-solving that may not be fully specified or may not guarantee correct or optimal results, especially in problem domains where there is no well-defined correct or optimal result. For example, social media recommender systems rely on heuristics in such a way that, although widely characterized as "algorithms" in 21st-century popular media, cannot deliver correct results due to the nature of the problem. As an effective method, an algorithm can be expressed within a finite amount of space and time and in a well-defined formal language for calculating a function.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "An algorithm is any vague approach to a problem."}, {"id": "B", "text": "Heuristics always guarantee optimal results."}, {"id": "C", "text": "An algorithm must run forever."}, {"id": "D", "text": "An algorithm is a finite sequence of rigorous instructions for solving a problem, distinct from a heuristic that may not guarantee correct results."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Algorithm", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Algorithm', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-CI008', 'D', ARRAY['D']::TEXT[], 'The passage defines algorithms, describes conditionals and automation, and contrasts them with heuristics.', '{"A": "The text defines an algorithm as a finite sequence of mathematically rigorous instructions.", "C": "The text says it is a finite sequence.", "B": "The text says a heuristic may not guarantee correct or optimal results."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-INF008', 'HDSAT-RW-M34-INF008', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Inferences', 'Medium', 'multiple_choice', 'In mathematics and computer science, an algorithm ( ) is a finite sequence of mathematically rigorous instructions, typically used to solve a class of specific problems or to perform a computation. Algorithms are used as specifications for performing calculations and data processing. More advanced algorithms can use conditionals to divert the code execution through various routes (referred to as automated decision-making) and deduce valid inferences (referred to as automated reasoning), achieving automation eventually. Using human characteristics as descriptors of machines in metaphorical ways was already practiced by Alan Turing with terms such as "memory", "search" and "stimulus". In contrast, a heuristic is an approach to problem-solving that may not be fully specified or may not guarantee correct or optimal results, especially in problem domains where there is no well-defined correct or optimal result. For example, social media recommender systems rely on heuristics in such a way that, although widely characterized as "algorithms" in 21st-century popular media, cannot deliver correct results due to the nature of the problem. As an effective method, an algorithm can be expressed within a finite amount of space and time and in a well-defined formal language for calculating a function.
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-INF008', 'B', ARRAY['B']::TEXT[], 'Lack of guaranteed correctness separates heuristics from rigorous algorithms.', '{"C": "The text contrasts heuristics with algorithms that specify rigorous instructions.", "D": "The text describes heuristics as possibly not fully specified.", "A": "The text says they may not guarantee optimal results."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
