INSERT INTO public.questions (id, external_id, assessments, section, domain, skill, difficulty, format, stimulus, prompt, choices, figure_metadata, source_id, source_name, license, attribution, is_released_practice_set, status) VALUES ('RW-M34-CI009', 'HDSAT-RW-M34-CI009', ARRAY['SAT', 'PSAT/NMSQT', 'PSAT 10', 'PSAT 8/9']::TEXT[], 'Reading and Writing', 'Information and Ideas', 'Central Ideas and Details', 'Medium', 'multiple_choice', 'A data center is a facility for storing, managing, and disseminating digital information, including computer systems and associated components, IT infrastructure, equipment to maintain the proper conditions for the operation of electronic equipment, and training artificial intelligence. According to IBM, data centers date back to the 1940s, with the United States military''s Electrical Numerical Integrator and Computer (ENIAC) as an early example. Data centers have different models depending on their workloads. An enterprise (on-premises) model hosts IT infrastructure and data on-premises, while cloud data centers, including hyperscale data centers, house IT infrastructure resources through an internet connection used by cloud service providers such as Amazon Web Services, Google Cloud Platform, IBM Cloud, and Microsoft Azure. They frequently contain thousands of servers and many miles of high-speed data connection equipment, with the largest occupying up to 10,000,000 sq ft (930,000 m2). Managed service data centers have third-party managers hired on behalf of a company, which leases the equipment and infrastructure instead of buying it. Colocation data centers allow companies to rent space in an off-site data center owned by others, with the colocation data center hosting the infrastructure while the company provides and manages the components. Edge data centers are smaller, decentralized facilities located closer to end users and devices. In the 2024 U.S.', 'Which choice best states the main idea of the text?', '[{"id": "A", "text": "All data centers are owned by the same company."}, {"id": "B", "text": "A data center is a facility for storing, managing, and disseminating digital information, organized under several deployment models."}, {"id": "C", "text": "A data center is a single desktop computer."}, {"id": "D", "text": "Data centers first appeared in the 21st century."}]'::jsonb, NULL, 'wikipedia-cc-by-sa-4', 'Wikipedia (CC BY-SA 4.0)', 'CC BY-SA 4.0', 'Wikipedia, "Data center", CC BY-SA 4.0, retrieved 2026-11-02. https://en.wikipedia.org/wiki/Data_center', FALSE, 'active') ON CONFLICT (id) DO UPDATE SET external_id = EXCLUDED.external_id, assessments = EXCLUDED.assessments, section = EXCLUDED.section, domain = EXCLUDED.domain, skill = EXCLUDED.skill, difficulty = EXCLUDED.difficulty, format = EXCLUDED.format, stimulus = EXCLUDED.stimulus, prompt = EXCLUDED.prompt, choices = EXCLUDED.choices, figure_metadata = EXCLUDED.figure_metadata, source_id = EXCLUDED.source_id, source_name = EXCLUDED.source_name, license = EXCLUDED.license, attribution = EXCLUDED.attribution, is_released_practice_set = EXCLUDED.is_released_practice_set, status = 'active';
INSERT INTO public.question_keys (question_id, correct_answer, acceptable_answers, explanation, distractor_rationales) VALUES ('RW-M34-CI009', 'B', ARRAY['B']::TEXT[], 'The passage defines data centers, describes their models, and traces their history.', '{"C": "The text defines a data center as a facility for digital information and IT infrastructure.", "A": "The text lists enterprise, cloud, managed service, colocation, and edge models.", "D": "The text says data centers date back to the 1940s."}'::jsonb) ON CONFLICT (question_id) DO UPDATE SET correct_answer = EXCLUDED.correct_answer, acceptable_answers = EXCLUDED.acceptable_answers, explanation = EXCLUDED.explanation, distractor_rationales = EXCLUDED.distractor_rationales;
